#include <bits/stdc++.h>
using namespace std;
class Solution {int best;void dfs(vector<int>& c,int i,vector<int>& load,int cur){if(cur>=best)return;if(i==(int)c.size()){best=cur;return;}unordered_set<int> seen;for(int j=0;j<(int)load.size();++j){if(!seen.insert(load[j]).second)continue;load[j]+=c[i];dfs(c,i+1,load,max(cur,load[j]));load[j]-=c[i];}}public:int distributeCookies(vector<int>& cookies,int k){sort(cookies.rbegin(),cookies.rend());best=accumulate(cookies.begin(),cookies.end(),0);vector<int> load(k);dfs(cookies,0,load,0);return best;}};
